        max_diff = float('-inf')
        current_sum = 0

        for num in arr:
            current_sum += num
            if current_sum > max_diff:
                max_diff = current_sum
            if current_sum < 0:
                current_sum = 0

        return max_diff

    # Convert binary string to an array where 0 -> +1 and 1 -> -1
