def max_sub_array_sum_repeated(arr, n, k):
    def kadane(array):
        max_ending_here = max_so_far = array[0]
        for x in array[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(arr)
    if k == 1:
        return kadane(arr)

    # Kadane's algorithm for the array repeated twice
    extended_array = arr * 2
    max_sum_twice = kadane(extended_array)

    if total_sum > 0:
        return max_sum_twice + (k - 2) * total_sum
    else:
        return max_sum_twice

# Example usage and test
assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30
