def max_aggregate(data):
    # Create a dictionary to store the aggregate values
    aggregate = {}

    # Iterate over the list of tuples
    for name, value in data:
        # Add the value to the corresponding name in the dictionary
        if name in aggregate:
            aggregate[name] += value
        else:
            aggregate[name] = value

    # Find the name with the maximum aggregate value
    max_name = max(aggregate, key=aggregate.get)

    # Return the name and the maximum aggregate value as a tuple
    return (max_name, aggregate[max_name])

