def get_max_sum(n, memo=None):
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 0

    # Calculate the maximum sum using the given equation
    max_sum = max(
        get_max_sum(n // 2, memo) + get_max_sum(n // 3, memo) + get_max_sum(n // 4, memo) + get_max_sum(n // 5, memo),
        n
    )

    # Save the result in memoization dictionary
    memo[n] = max_sum
    return max_sum
