def get_ludic(n):
    def generate_ludic_numbers(limit):
        ludics = list(range(1, limit + 1))  # Start with all numbers from 1 to limit
        i = 1  # Start with the first valid index (corresponding to the number 2)
        while i < len(ludics):
            step = ludics[i]  # Get the current step size (ludic number)
            ludics = [num for j, num in enumerate(ludics) if j == 0 or (j % step != 0)]  # Filter out numbers based on the step
            i += 1  # Move to the next index
        return ludics

    return generate_ludic_numbers(n)
