def move_num(input_string):
    letters_part = []
    numbers_part = []
    temp_num = ""

    for char in input_string:
        if char.isdigit():
            temp_num += char
        else:
            if temp_num:
                numbers_part.append(temp_num)
                temp_num = ""
            letters_part.append(char)

    if temp_num:  # Append any final number found
        numbers_part.append(temp_num)

    return ''.join(letters_part) + ''.join(numbers_part)

